// RemoteOK API returns array; first element is metadata, rest are jobs
const raw = $input.first().json;
const data = Array.isArray(raw) ? raw : [raw];
const jobs = data.slice(1); // skip metadata object

return jobs
  .filter(j => j && j.position)
  .map(j => ({
    json: {
      job_title: (j.position || '').trim(),
      company: (j.company || '').trim(),
      job_url: j.url ? (j.url.startsWith('http') ? j.url : `https://remoteok.com${j.url}`) : '',
      source: 'RemoteOK',
      location_text: j.location || 'worldwide',
      salary: j.salary || '',
      description: (j.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
      posted_date: j.date || '',
      tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.tags || ''),
      job_id: j.url || `remoteok-${j.id || Date.now()}`
    }
  }));

const raw = $input.first().json;
const jobs = raw.jobs || (Array.isArray(raw) ? raw : []);

return jobs.map(j => ({
  json: {
    job_title: (j.title || '').trim(),
    company: (j.company_name || '').trim(),
    job_url: j.url || '',
    source: 'Remotive',
    location_text: j.candidate_required_location || 'worldwide',
    salary: j.salary || '',
