    tags: Array.isArray(j.tags) ? j.tags.join(', ') : '',
    job_id: j.url || `remotive-${j.id}`
  }
}));

return $input.all().map(item => {
  const j = item.json;
  // WWR title format: "COMPANY NAME: Job Title [Category]"
  const titleRaw = j.title || '';
  const colonIdx = titleRaw.indexOf(':');
  const company = colonIdx > -1 ? titleRaw.slice(0, colonIdx).trim() : 'Unknown';
  const jobTitle = colonIdx > -1 ? titleRaw.slice(colonIdx + 1).trim() : titleRaw.trim();
  const cleanTitle = jobTitle.replace(/\[.*?\]/g, '').trim();

  return {
    json: {
      job_title: cleanTitle,
      company: company,
      job_url: j.link || j.guid || '',
      source: 'We Work Remotely',
      location_text: 'worldwide',
      salary: '',
      description: (j['content:encoded'] || j.content || j.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
      posted_date: j.pubDate || j.isoDate || '',
      tags: Array.isArray(j.categories) ? j.categories.join(', ') : (j.category || ''),
      job_id: j.link || j.guid || `wwr-${Date.now()}-${Math.random()}`
    }
  };
});

