  if (!raw || raw.error || typeof raw === 'string') return [];
  const jobs = raw.jobs || raw.startups || raw.data || (Array.isArray(raw) ? raw : []);
  return jobs.map(j => ({
    json: {
      job_title: (j.title || j.role || j.name || '').trim(),
