// NOTE: Otta requires authentication. If fetch fails, this returns empty.
try {
  const raw = $input.first().json;
  if (!raw || raw.error || typeof raw === 'string') return [];
  const jobs = raw.jobs || raw.results || raw.data || (Array.isArray(raw) ? raw : []);
  return jobs.map(j => {
    const companyName = (j.company && j.company.name) || j.companyName || '';
    const minSal = j.salaryMin || j.salary_min;
    const maxSal = j.salaryMax || j.salary_max;
    const currency = j.salaryCurrency || '$';
    const salary = minSal ? `${currency}${minSal.toLocaleString()}–${maxSal ? maxSal.toLocaleString() : '?'}` : '';
    const desc = Array.isArray(j.bullets) ? j.bullets.join(' ') : (j.description || '');
    return {
      json: {
        job_title: (j.function || j.title || j.jobTitle || '').trim(),
        company: companyName.trim(),
        job_url: j.externalId ? `https://app.otta.com/jobs/${j.externalId}` : (j.url || ''),
        source: 'Otta',
        location_text: j.remote ? 'worldwide remote' : '',
        salary: salary,
        description: desc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
        posted_date: j.createdAt || '',
        tags: Array.isArray(j.tags) ? j.tags.join(', ') : '',
        job_id: `otta-${j.id || j.externalId}`
      }
    };
  });
} catch(e) {
  console.log('Otta normalize error:', e.message);
  return [];
}

// Keep jobs that match role keywords OR remote eligibility keywords.
const ROLE_KEYWORDS = [
  'data analyst', 'data scientist', 'junior data scientist',
  'business intelligence', 'bi analyst', 'marketing analyst',
  'growth analyst', 'performance marketing analyst',
  'ai marketing', 'ai automation', 'automation specialist',
  'ai workflow', 'creative strategist', 'martech analyst',
  'martech', 'analytics engineer'
];

const REMOTE_KEYWORDS = [
  'async remote', 'asynchronous remote', 'worldwide remote',
  'global remote', 'work from anywhere', 'remote data analyst',
  'remote data scientist', 'remote marketing analyst',
  'remote growth analyst', 'remote bi analyst',
  'remote automation specialist', 'remote ai workflow consultant'
];

return $input.all().filter(item => {
  const j = item.json;
  const searchText = [
    j.job_title || '',
    j.description || '',
    j.location_text || '',
    j.tags || ''
  ].join(' ').toLowerCase();

  return ROLE_KEYWORDS.some(k => searchText.includes(k))
      || REMOTE_KEYWORDS.some(k => searchText.includes(k));
});

// Compare incoming jobs against Google Sheets existing data.
// Uses $('Get Existing Jobs') to reference parallel-run node.
const newJobs = $input.all();

let existingUrls = new Set();
let existingKeys = new Set();

try {
  const sheetRows = $('Get Existing Jobs').all();
  sheetRows.forEach(row => {
    const url = (row.json['job_url'] || row.json['Job URL'] || '').trim();
    const company = (row.json['company'] || row.json['Company'] || '').toLowerCase().trim();
    const title = (row.json['job_title'] || row.json['Job Title'] || '').toLowerCase().trim();
    if (url) existingUrls.add(url);
    if (company && title) existingKeys.add(`${company}|||${title}`);
  });
} catch(e) {
  // First run or sheet is empty – proceed without dedup
  console.log('Dedup: could not read existing sheet, proceeding:', e.message);
}

const seenThisRun = new Set();

return newJobs.filter(item => {
  const url = (item.json.job_url || '').trim();
  const company = (item.json.company || '').toLowerCase().trim();
  const title = (item.json.job_title || '').toLowerCase().trim();
  const key = `${company}|||${title}`;
  const dedupeId = url || key;

  if (!dedupeId || dedupeId === '|||') return false;
  if (url && existingUrls.has(url)) return false;
  if (existingKeys.has(key)) return false;
  if (seenThisRun.has(dedupeId)) return false;

  seenThisRun.add(dedupeId);
  return true;
});

// Reject jobs with hard country/location/timezone restrictions.
// Tag each job with filter result for downstream branching.

const HARD_REJECT = [
  'us only', 'usa only', 'united states only', 'u.s. only', 'us-only',
  'canada only', 'uk only', 'united kingdom only', 'gb only',
