  'global remote', 'fully distributed', 'fully remote',
  'all timezones', 'any timezone', 'timezone agnostic',
  'time zone agnostic', 'apac', 'international contractors',
  'open to contractors', 'b2b contractor', 'contractor agreement',
  'deel', 'remote.com', 'oyster hr', 'oyster.com',
