// Parse the OpenAI response and merge AI tags back onto the job item.
const j = $input.item.json;

let aiResult = {
  taiwan_eligible: 'unclear',
  reason: 'AI response could not be parsed',
  location_risk: 'medium',
  timezone_risk: 'medium',
  contractor_possible: 'unclear',
  decision: 'manual_check'
};

try {
  // n8n OpenAI node returns message.content
  const rawText = j.message?.content
    || j.choices?.[0]?.message?.content
    || j.content
    || j.text
    || '';

  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    aiResult = {
      taiwan_eligible: parsed.taiwan_eligible || 'unclear',
      reason: parsed.reason || '',
      location_risk: parsed.location_risk || 'medium',
      timezone_risk: parsed.timezone_risk || 'medium',
      contractor_possible: parsed.contractor_possible || 'unclear',
      decision: parsed.decision || 'manual_check'
    };
  }
} catch(e) {
  console.log('AI parse error:', e.message);
}

// Retrieve original job data stored in pairedItem
const originalJob = {};
// The previous execution context passes through all fields on the item
return {
  json: {
    ...j,
    taiwan_eligible: aiResult.taiwan_eligible,
    taiwan_reason: aiResult.reason,
    location_risk: aiResult.location_risk,
    timezone_risk: aiResult.timezone_risk,
    contractor_possible: aiResult.contractor_possible,
    ai_decision: aiResult.decision
  }
};

const ASYNC_POSITIVE = [
  'async', 'asynchronous', 'flexible hours', 'flexible schedule',
  'distributed team', 'remote first', 'remote-first',
  'low meeting culture', 'low-meeting', 'work across time zones',
  'timezone flexible', 'no mandatory meetings', 'async communication',
  'work your own hours', 'own schedule', 'results driven',
  'results-oriented', 'outcome-based', 'flexible working hours'
];

const ASYNC_NEGATIVE = [
  'strict 9 to 5', 'strict 9-5', 'required hours 9am',
  'fixed us hours', 'fixed est hours', 'fixed pst hours',
  'fixed cet hours', 'daily live calls required',
  'must overlap full business day', 'must be available during us business hours',
  'must work same hours', 'required to be online 9am',
  'core hours required', 'required overlap'
];

return $input.all().map(item => {
  const j = item.json;
  const text = (j.description || '').toLowerCase();

  const hasNegative = ASYNC_NEGATIVE.some(k => text.includes(k));
  const positiveMatches = ASYNC_POSITIVE.filter(k => text.includes(k));

  let asyncLevel = 'low';
  if (text.includes('async') || text.includes('asynchronous')) asyncLevel = 'high';
  else if (positiveMatches.length >= 2) asyncLevel = 'high';
  else if (positiveMatches.length === 1) asyncLevel = 'medium';

  // Downgrade if negative signals present
  if (hasNegative && asyncLevel === 'high') asyncLevel = 'medium';
  if (hasNegative && asyncLevel === 'medium') asyncLevel = 'low';

  return {
    json: {
      ...j,
      async_level: asyncLevel,
      async_keywords: positiveMatches.slice(0, 5).join(', ')
    }
  };
});

const PRIMARY_ROLES = [
  'data analyst', 'data scientist', 'junior data scientist',
  'business intelligence analyst', 'bi analyst', 'marketing analyst',
  'performance marketing analyst', 'growth analyst', 'ai marketing specialist',
  'ai automation specialist', 'ai workflow consultant', 'martech analyst'
];

const ADJACENT_ROLES = [
  'analyst', 'scientist', 'automation', 'marketing', 'ai', 'data', 'growth', 'intelligence'
];

return $input.all().map(item => {
  const j = item.json;
  const text = [j.description || '', j.location_text || '', j.job_title || '', j.tags || ''].join(' ').toLowerCase();
  const jobTitle = (j.job_title || '').toLowerCase();
  let score = 0;

  // === TAIWAN ELIGIBILITY (0–40 pts) ===
  const eligible = j.taiwan_eligible || 'unclear';
  if (eligible === 'yes') {
    if (/worldwide|work from anywhere|global remote/.test(text)) score += 40;
    else if (/apac/.test(text)) score += 30;
    else if (/contractor|anywhere/.test(text)) score += 35;
    else score += 25;
  } else if (eligible === 'unclear') {
    if (j.has_clear_pass_signal) score += 25;
    else if (!/us only|canada only|uk only|eu only|europe only|australia only/.test(text)) score += 20;
    else score += 5;
  }
  // taiwan_eligible === 'no' → 0 pts

  // === ASYNC FIT (0–25 pts) ===
  const asyncLvl = j.async_level || 'low';
  if (asyncLvl === 'high') score += 25;
  else if (asyncLvl === 'medium') score += 20;
  else if (/distributed team|remote.?first/.test(text)) score += 10;

  // === ROLE FIT (0–25 pts) ===
  const isPrimaryRole = PRIMARY_ROLES.some(r => jobTitle.includes(r));
  const adjacentCount = ADJACENT_ROLES.filter(r => jobTitle.includes(r)).length;
  if (isPrimaryRole) score += 25;
  else if (adjacentCount >= 2) score += 20;
  else if (adjacentCount >= 1) score += 15;

  // === SALARY (0–25 pts) ===
  const salaryText = (j.salary || '').replace(/[,$]/g, ' ');
  const amounts = [...salaryText.matchAll(/(\d+)k?/gi)].map(m => {
    const n = parseInt(m[1]);
    return salaryText.toLowerCase().includes(`${m[1]}k`) ? n * 1000 : n;
  }).filter(n => n > 0);

  let salaryScore = 0;
  if (amounts.length > 0) {
    const maxAmt = Math.max(...amounts);
    // Treat as annual if > 1000, monthly otherwise
    const monthly = maxAmt > 12000 ? maxAmt / 12 : maxAmt;
    if (monthly >= 5000) salaryScore = 25;
    else if (monthly >= 3000) salaryScore = 15;
    else salaryScore = 10;
  }
  score += salaryScore;

  // === ROLE CATEGORY ===
  let roleCategory = 'other';
  if (/data scientist|machine learning|ml engineer/.test(jobTitle)) roleCategory = 'data_science';
  else if (/data analyst|bi analyst|business intelligence/.test(jobTitle)) roleCategory = 'data_analytics';
  else if (/marketing analyst|growth analyst|performance marketing/.test(jobTitle)) roleCategory = 'marketing_analytics';
  else if (/ai marketing|ai automation|ai workflow/.test(jobTitle)) roleCategory = 'ai_marketing';
  else if (/automation specialist|workflow consultant/.test(jobTitle)) roleCategory = 'automation';
  else if (/analyst/.test(jobTitle)) roleCategory = 'analytics';

  // === WHY GOOD FIT ===
  const reasons = [];
  if (eligible === 'yes') reasons.push('Taiwan eligible confirmed');
  if (eligible === 'unclear' && j.has_clear_pass_signal) reasons.push('likely Taiwan eligible');
  if (asyncLvl === 'high') reasons.push('fully async');
  if (asyncLvl === 'medium') reasons.push('flexible hours');
  if (isPrimaryRole) reasons.push('matches target role');
  if (salaryScore >= 25) reasons.push('excellent salary');
  else if (salaryScore >= 15) reasons.push('good salary');
  if (j.contractor_possible === 'yes') reasons.push('contractor-friendly');
  if (/deel|remote\.com|oyster/.test(text)) reasons.push('uses global payroll (Deel/Remote/Oyster)');
  if (/apac/.test(text)) reasons.push('APAC-friendly timezone');

  // === ONE-SENTENCE RULE ===
  const passesOneRule = (
    eligible !== 'no' &&
    j.location_risk !== 'high' &&
    j.timezone_risk !== 'high' &&
    !text.includes('us only') &&
    !text.includes('eu only')
  );

  return {
    json: {
      ...j,
      score: Math.min(score, 100),
      role_category: roleCategory,
      why_good_fit: reasons.join(', '),
      passes_one_rule: passesOneRule,
      date_found: new Date().toLocaleString('en-CA', {timeZone: 'Asia/Taipei'}).split(',')[0],
      application_status: 'new',
      notes: ''
    }
  };
});

const allJobs = $input.all();
const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Taipei'
});

// Sort by score descending
const sorted = [...allJobs].sort((a, b) => (b.json.score || 0) - (a.json.score || 0));

const topJobs = sorted.filter(j => j.json.score >= 85 && j.json.taiwan_eligible !== 'no');
const goodJobs = sorted.filter(j => j.json.score >= 70 && j.json.score < 85 && j.json.taiwan_eligible !== 'no');
const manualJobs = sorted.filter(j => j.json.taiwan_eligible === 'unclear' && j.json.score >= 70);

// --- Rejection stats (tracked from what we see) ---
const rejectedUS = $input.all().filter(j => /(us only|united states only)/.test((j.json.hard_filter_reject_reason||'').toLowerCase())).length;
const rejectedEU = $input.all().filter(j => /(eu only|europe only)/.test((j.json.hard_filter_reject_reason||'').toLowerCase())).length;
const rejectedHybrid = $input.all().filter(j => /(hybrid|onsite|on-site)/.test((j.json.hard_filter_reject_reason||'').toLowerCase())).length;
const rejectedTimezone = $input.all().filter(j => j.json.timezone_risk === 'high').length;

function jobBlock(item, idx) {
  const j = item.json;
  let block = `${idx}. ${j.job_title}\n`;
  block += `   Company: ${j.company}\n`;
  block += `   Score: ${j.score}/100\n`;
  block += `   Taiwan Eligible: ${j.taiwan_eligible}\n`;
  block += `   Reason: ${j.taiwan_reason || 'See job description'}\n`;
  block += `   Async Level: ${j.async_level}\n`;
  block += `   Timezone Risk: ${j.timezone_risk}\n`;
  block += `   Salary: ${j.salary || 'Not listed'}\n`;
  block += `   Why It Fits Jerry: ${j.why_good_fit || 'Matches target profile'}\n`;
  block += `   Apply: ${j.job_url}\n`;
  return block;
}

let digest = `Daily Taiwan Eligible Async Remote Jobs\n`;
digest += `${today}\n`;
digest += `${'═'.repeat(45)}\n\n`;

if (topJobs.length === 0 && goodJobs.length === 0) {
  digest += `No jobs met the Taiwan eligibility criteria today. Try again tomorrow.\n\n`;
} else {
  if (topJobs.length > 0) {
    digest += `⭐ TOP PRIORITY JOBS (Score 85+)\n${'─'.repeat(40)}\n`;
    topJobs.slice(0, 5).forEach((j, i) => { digest += '\n' + jobBlock(j, i + 1); });
    digest += '\n';
  }
  if (goodJobs.length > 0) {
    digest += `✅ STRONG MATCHES (Score 70–84)\n${'─'.repeat(40)}\n`;
    goodJobs.slice(0, 5).forEach((j, i) => { digest += '\n' + jobBlock(j, topJobs.length + i + 1); });
    digest += '\n';
  }
}

if (manualJobs.length > 0) {
  digest += `⚠️ MANUAL CHECK NEEDED (Eligibility Unclear, Score 70+)\n${'─'.repeat(40)}\n`;
  manualJobs.slice(0, 5).forEach((item, i) => {
    const j = item.json;
    digest += `\n${i + 1}. ${j.job_title} at ${j.company} (Score: ${j.score})\n`;
    digest += `   Reason unclear: ${j.taiwan_reason || 'Check manually'}\n`;
    digest += `   ${j.job_url}\n`;
  });
  digest += '\n';
}

digest += `${'═'.repeat(45)}\n`;
digest += `📊 TODAY'S SUMMARY\n`;
digest += `${'─'.repeat(40)}\n`;
digest += `Total processed today: ${allJobs.length}\n`;
digest += `High priority (85+): ${topJobs.length}\n`;
digest += `Strong matches (70–84): ${goodJobs.length}\n`;
digest += `Manual check needed: ${manualJobs.length}\n`;
digest += `\nRejection breakdown:\n`;
digest += `  - US only: ${rejectedUS}\n`;
digest += `  - EU only: ${rejectedEU}\n`;
digest += `  - Hybrid/onsite: ${rejectedHybrid}\n`;
digest += `  - High timezone risk: ${rejectedTimezone}\n`;
digest += `\nView all results: Taiwan Eligible Async Remote Jobs (Google Sheets)\n`;

return [{
  json: {
    digest_text: digest,
    digest_subject: `[${new Date().toLocaleDateString('en-US', {month: 'short', day: 'numeric', timeZone: 'Asia/Taipei'})}] ${topJobs.length} High-Priority + ${goodJobs.length} Strong Matches Found`,
    top_jobs_count: topJobs.length,
    good_jobs_count: goodJobs.length,
    manual_check_count: manualJobs.length,
    total_processed: allJobs.length
  }
}];
